#define CHECK(call) do { VkResult r=(call); if(r!=VK_SUCCESS){fprintf(stderr,"VK_ANDROID_FAIL line=%d %s result=%d\n",__LINE__,#call,r);exit(4);} } while(0)
#define REQUIRE(x) do { if(!(x)){fprintf(stderr,"VK_ANDROID_FAIL line=%d %s\n",__LINE__,#x);exit(5);} } while(0)
static VkDevice device;static VkPhysicalDevice physical;static VkQueue queue;static VkCommandPool pool;
static uint32_t family;
