static void two_queue_dependency_test(void) {
 VkQueue upload=VK_NULL_HANDLE;vkGetDeviceQueue(device,family,1,&upload);REQUIRE(upload&&upload!=queue);
 VkBufferCreateInfo bi={.sType=VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO,.size=4096,.usage=VK_BUFFER_USAGE_TRANSFER_SRC_BIT|VK_BUFFER_USAGE_TRANSFER_DST_BIT,.sharingMode=VK_SHARING_MODE_EXCLUSIVE};VkBuffer buffer;CHECK(vkCreateBuffer(device,&bi,NULL,&buffer));VkMemoryRequirements req;vkGetBufferMemoryRequirements(device,buffer,&req);VkPhysicalDeviceMemoryProperties props;vkGetPhysicalDeviceMemoryProperties(physical,&props);unsigned type=0;for(;type<props.memoryTypeCount;type++)if((req.memoryTypeBits&(1u<<type))&&((props.memoryTypes[type].propertyFlags&(VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT|VK_MEMORY_PROPERTY_HOST_COHERENT_BIT))==(VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT|VK_MEMORY_PROPERTY_HOST_COHERENT_BIT)))break;REQUIRE(type<props.memoryTypeCount);VkMemoryAllocateInfo ai={.sType=VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO,.allocationSize=req.size,.memoryTypeIndex=type};VkDeviceMemory memory;CHECK(vkAllocateMemory(device,&ai,NULL,&memory));CHECK(vkBindBufferMemory(device,buffer,memory,0));uint32_t *map=NULL;CHECK(vkMapMemory(device,memory,0,VK_WHOLE_SIZE,0,(void**)&map));
 for(unsigned mode=0;mode<2;mode++)for(unsigned round=0;round<4;round++){
  memset(map,0,4096);uint32_t pattern=0x10203040+mode*16+round;VkCommandBuffer cmd[2];VkCommandBufferAllocateInfo ca={.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO,.commandPool=pool,.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY,.commandBufferCount=2};CHECK(vkAllocateCommandBuffers(device,&ca,cmd));VkCommandBufferBeginInfo begin={.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};CHECK(vkBeginCommandBuffer(cmd[0],&begin));vkCmdFillBuffer(cmd[0],buffer,0,2048,pattern);CHECK(vkEndCommandBuffer(cmd[0]));CHECK(vkBeginCommandBuffer(cmd[1],&begin));VkBufferCopy copy={.srcOffset=0,.dstOffset=2048,.size=2048};vkCmdCopyBuffer(cmd[1],buffer,buffer,1,&copy);VkBufferMemoryBarrier b={.sType=VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER,.srcAccessMask=VK_ACCESS_TRANSFER_WRITE_BIT,.dstAccessMask=VK_ACCESS_HOST_READ_BIT,.srcQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED,.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED,.buffer=buffer,.size=VK_WHOLE_SIZE};vkCmdPipelineBarrier(cmd[1],VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_HOST_BIT,0,0,NULL,1,&b,0,NULL);CHECK(vkEndCommandBuffer(cmd[1]));
  VkSemaphoreTypeCreateInfo ti={.sType=VK_STRUCTURE_TYPE_SEMAPHORE_TYPE_CREATE_INFO,.semaphoreType=VK_SEMAPHORE_TYPE_TIMELINE,.initialValue=0};VkSemaphoreCreateInfo si={.sType=VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO,.pNext=mode?&ti:NULL};VkSemaphore ready;CHECK(vkCreateSemaphore(device,&si,NULL,&ready));VkFence f[2];VkFenceCreateInfo fi={.sType=VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};CHECK(vkCreateFence(device,&fi,NULL,&f[0]));CHECK(vkCreateFence(device,&fi,NULL,&f[1]));uint64_t value=7;VkTimelineSemaphoreSubmitInfo wait={.sType=VK_STRUCTURE_TYPE_TIMELINE_SEMAPHORE_SUBMIT_INFO,.waitSemaphoreValueCount=1,.pWaitSemaphoreValues=&value};VkTimelineSemaphoreSubmitInfo signal={.sType=VK_STRUCTURE_TYPE_TIMELINE_SEMAPHORE_SUBMIT_INFO,.signalSemaphoreValueCount=1,.pSignalSemaphoreValues=&value};VkPipelineStageFlags stage=VK_PIPELINE_STAGE_TRANSFER_BIT;
  VkSubmitInfo consumer={.sType=VK_STRUCTURE_TYPE_SUBMIT_INFO,.pNext=mode?&wait:NULL,.waitSemaphoreCount=1,.pWaitSemaphores=&ready,.pWaitDstStageMask=&stage,.commandBufferCount=1,.pCommandBuffers=&cmd[1]};
  VkSubmitInfo producer={.sType=VK_STRUCTURE_TYPE_SUBMIT_INFO,.pNext=mode?&signal:NULL,.commandBufferCount=1,.pCommandBuffers=&cmd[0],.signalSemaphoreCount=1,.pSignalSemaphores=&ready};
  if(mode){
   // Timeline semaphores permit a wait to be submitted before its signal.
   CHECK(vkQueueSubmit(queue,1,&consumer,f[1]));usleep(50000);REQUIRE(vkGetFenceStatus(device,f[1])==VK_NOT_READY);
   CHECK(vkQueueSubmit(upload,1,&producer,f[0]));
  }else{
   // VUID-vkQueueSubmit-pWaitSemaphores-03238: binary signals must already
   // be submitted. The dependent GPU copy still proves cross-queue ordering.
   CHECK(vkQueueSubmit(upload,1,&producer,f[0]));
   CHECK(vkQueueSubmit(queue,1,&consumer,f[1]));
  }
  CHECK(vkWaitForFences(device,2,f,VK_TRUE,5000000000ULL));for(unsigned i=0;i<1024;i++)REQUIRE(map[i]==pattern);
  CHECK(vkQueueWaitIdle(queue));CHECK(vkQueueWaitIdle(upload));vkFreeCommandBuffers(device,pool,2,cmd);vkDestroyFence(device,f[0],NULL);vkDestroyFence(device,f[1],NULL);vkDestroySemaphore(device,ready,NULL);printf("VK_ANDROID_TWO_QUEUE_ORDERED_GPU_COPY_PASS mode=%s round=%u pattern=%08x\n",mode?"timeline":"binary",round,pattern);
 }
 vkUnmapMemory(device,memory);vkDestroyBuffer(device,buffer,NULL);vkFreeMemory(device,memory,NULL);puts("VK_ANDROID_TWO_REAL_QUEUES_FUTURE_SIGNAL_AND_GPU_ORDER_PASS");
}

int main(int argc,char**argv) {
 int two_queues=argc==2&&!strcmp(argv[1],"--two-queues");REQUIRE(argc==1||two_queues);setbuf(stdout,NULL);VkApplicationInfo app={.sType=VK_STRUCTURE_TYPE_APPLICATION_INFO,.pApplicationName="M1 Android Vulkan qualification",.apiVersion=VK_API_VERSION_1_2};const char *ie[]={VK_KHR_SURFACE_EXTENSION_NAME,VK_KHR_ANDROID_SURFACE_EXTENSION_NAME};VkInstanceCreateInfo ci={.sType=VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO,.pApplicationInfo=&app,.enabledExtensionCount=2,.ppEnabledExtensionNames=ie};VkInstance instance;CHECK(vkCreateInstance(&ci,NULL,&instance));uint32_t n=0;CHECK(vkEnumeratePhysicalDevices(instance,&n,NULL));REQUIRE(n==1);CHECK(vkEnumeratePhysicalDevices(instance,&n,&physical));VkPhysicalDeviceDriverProperties driver={.sType=VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_DRIVER_PROPERTIES};VkPhysicalDeviceProperties2 p={.sType=VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2,.pNext=&driver};vkGetPhysicalDeviceProperties2(physical,&p);printf("VK_ANDROID_ACTUAL_DRIVER name=%s driver=%s id=%u api=%x\n",p.properties.deviceName,driver.driverName,driver.driverID,p.properties.apiVersion);REQUIRE(driver.driverID==VK_DRIVER_ID_MESA_HONEYKRISP&&p.properties.deviceType==VK_PHYSICAL_DEVICE_TYPE_INTEGRATED_GPU);
 vkGetPhysicalDeviceQueueFamilyProperties(physical,&n,NULL);REQUIRE(n&&n<64);VkQueueFamilyProperties q[64];vkGetPhysicalDeviceQueueFamilyProperties(physical,&n,q);for(family=0;family<n;family++)if(q[family].queueFlags&VK_QUEUE_GRAPHICS_BIT)break;REQUIRE(family<n);printf("VK_ANDROID_ACTUAL_QUEUE_COUNT %u\n",q[family].queueCount);REQUIRE(q[family].queueCount>=(two_queues?2u:1u));float priorities[2]={1,1};VkDeviceQueueCreateInfo qi={.sType=VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO,.queueFamilyIndex=family,.queueCount=two_queues?2u:1u,.pQueuePriorities=priorities};const char *de[]={VK_KHR_SWAPCHAIN_EXTENSION_NAME,VK_ANDROID_EXTERNAL_MEMORY_ANDROID_HARDWARE_BUFFER_EXTENSION_NAME};VkPhysicalDeviceTimelineSemaphoreFeatures tf={.sType=VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_TIMELINE_SEMAPHORE_FEATURES,.timelineSemaphore=VK_TRUE};VkDeviceCreateInfo di={.sType=VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO,.pNext=two_queues?&tf:NULL,.queueCreateInfoCount=1,.pQueueCreateInfos=&qi,.enabledExtensionCount=2,.ppEnabledExtensionNames=de};CHECK(vkCreateDevice(physical,&di,NULL,&device));vkGetDeviceQueue(device,family,0,&queue);getAhbProps=(PFN_vkGetAndroidHardwareBufferPropertiesANDROID)vkGetDeviceProcAddr(device,"vkGetAndroidHardwareBufferPropertiesANDROID");getMemoryAhb=(PFN_vkGetMemoryAndroidHardwareBufferANDROID)vkGetDeviceProcAddr(device,"vkGetMemoryAndroidHardwareBufferANDROID");REQUIRE(getAhbProps&&getMemoryAhb);VkCommandPoolCreateInfo pci={.sType=VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO,.queueFamilyIndex=family};CHECK(vkCreateCommandPool(device,&pci,NULL,&pool));if(two_queues)two_queue_dependency_test();ahb_import();ahb_export_buffer();swapchain(instance);vkDestroyCommandPool(device,pool,NULL);vkDestroyDevice(device,NULL);vkDestroyInstance(instance,NULL);puts("M1_VULKAN_ANDROID_AHB_AND_PRESENT_PASS");return 0;
}
